import{_ as i,o as e,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-08-29 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-08-29 -- Ceph Performance Meeting","date":"2019-08-29T00:00:00.000Z","updated":"2019-09-07T00:00:00.000Z","tags":["Ceph","性能优化","RGW","OSD","代码重构"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-08-29_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-08-29_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2019/2019-08-29_-_-_Ceph_Performance_Meeting.md"};function s(n,l,p,_,a,g){return e(),t("div",null,[...l[0]||(l[0]=[r("<p>会议纪要</p><p><strong>会议时间</strong>： 2019年8月29日 <strong>参会人员</strong>： 多位 Ceph 项目成员 <strong>会议主题</strong>： Ceph 项目进展讨论，重点讨论 RGW 和 OSD 性能优化、代码重构等议题。</p><p><strong>关键细节</strong>：</p><ul><li><strong>RGW 性能优化</strong>： <ul><li>讨论了优化目录条目过滤、减少解码操作、优化 JSON 格式输出等方式提升 RGW 性能。</li><li>探讨了使用 OMAP 缓存来减少重复数据访问，并提高数据检索效率。</li><li>讨论了优化 OSD 操作，减少内存占用，提高数据处理速度。</li></ul></li><li><strong>OSD 性能优化</strong>： <ul><li>讨论了优化目录条目处理，减少从 RocksDB 到 RGW 的数据传输。</li><li>讨论了优化数据哈希算法，支持数据排序，避免重复读取。</li><li>讨论了优化 JSON 格式输出，减少数据传输量。</li></ul></li><li><strong>代码重构</strong>： <ul><li>讨论了将 OSD 操作中的 case 语句拆分成独立函数，提高代码可读性和可维护性。</li><li>讨论了使用新的 JSON 解析库，优化数据解析效率。</li></ul></li></ul><p><strong>主要议题</strong>：</p><ul><li>如何进一步优化 RGW 性能，特别是目录条目处理和 JSON 格式输出。</li><li>如何优化 OSD 操作，减少内存占用，提高数据处理速度。</li><li>如何使用 OMAP 缓存来提高数据检索效率。</li><li>如何优化数据哈希算法，支持数据排序。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>将继续优化 RGW 性能，重点关注目录条目处理和 JSON 格式输出。</li><li>将继续优化 OSD 操作，减少内存占用，提高数据处理速度。</li><li>将探索使用 OMAP 缓存来提高数据检索效率。</li><li>将优化数据哈希算法，支持数据排序。</li><li>将将 OSD 操作中的 case 语句拆分成独立函数，提高代码可读性和可维护性。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>各成员将继续推进相关优化工作。</li><li>将定期召开会议，讨论项目进展和遇到的问题。</li><li>将及时更新项目文档，记录项目进展和决策。</li></ul><p><strong>其他事项</strong>：</p><ul><li>讨论了将小数据存储到 X-ADDERS 的提议，并决定不采纳该提议。</li><li>讨论了将小对象存储到 RocksDB 的提议，并决定将其作为备选方案进行研究。</li><li>讨论了将 OSD 操作中的 case 语句拆分成独立函数，提高代码可读性和可维护性。</li><li>讨论了使用新的 JSON 解析库，优化数据解析效率。</li></ul><p><strong>关键词</strong>：</p><ul><li>Ceph</li><li>RGW</li><li>OSD</li><li>性能优化</li><li>OMAP 缓存</li><li>数据哈希</li><li>JSON 格式</li><li>代码重构</li></ul>",14)])])}const S=i(o,[["render",s]]);export{u as __pageData,S as default};
